INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (127, 201, 'Standard Wax Ribbon', '../upload/image/20181226/20181226150105_20901.jpg', '<p></p><p>Standard Wax Ribbon <br/> Introduction:<br/> with excellent anti-static property and outstanding print quality,have the good print quality and the better label adaptability by using the high property printer and the simplified tabletop printer. The print speed can be up to 6 ips. It is suitable for many different types of label stocks. Premium wax has longer storage time, the better product stability, excellent heat resistance and abrasion, making the printer picture much more durable, clear and smooth.<br/> Print material:<br/> Recommended substrates:<br/> Art paper, coated paper, uncoated paper, glossy &amp; semi glossy paper, hangtag:<br/> Feature:<br/> 1.Extensive label adaptability<br/> 2.Good stability of products<br/> 3.High definition<br/> 4.Low print energy can extend the life of protect print head<br/> 5.Anti-static back coating can protect print head effectively.<br/> Technical parameters:<br/> Test Item Unit Test Equipment Standard<br/> Total thickness U m Thickness Tester 7.0+0.3<br/> Ink thickness U m Thickness Tester 2.6+0.4<br/> Electrostatic K v Static Tester 0.06<br/> Optical density D Transmission Type Density Spectrometer 1.3<br/> Color density D B Reflex density spectrometer 2.6<br/> Glossiness Gs Vancometer 51<br/> Application field:<br/> Price Label, Product Identification Label, Hang Tag, Packing Label, Train Tickets, Shipping &amp; Receiving Label, Logistical Label.</p> <p><br/></p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (127, 183, 'Printer Ribbons (date tape ribbons)', '../upload/image/20181226/20181226150049_14575.jpg', '<p></p><p>Printer Ribbons (date tape ribbons)</p> <p>Tape for dates (date tape,opening tape,thermal transfer color ribbon,PET thermal transfer opening ribbons,TAPE FOR DATES) were also called as thermal transfer color tape/ribbons,hot coding foil, hot ink roller.It was used as the footprint of BOPP/PET/CPP/PVC/PE/POF/TAPE film. This tape type it production date and shelf life of products. tape for dates includes opening tape,thermal transfer color ribbon,thermal transfer color tape,hot coding foil, date tapeshot ink roller,hot transfer film, thermal transfer ribbon, Printer Supplies,Printer Ribbons<br/> Thickness: 8.5,10.9-21.5-33.5-55UM (microns) . <br/> Width: 20mm,25mm,30mm,35mm,40mm,50mm,100mm,110mm, and so forth. <br/> Length: 100m,150m,200m,250m,360m,500m,1000m,<br/> Color: black,red,blue,yellow,white...<br/> Packing:24,36,72,100pieces/carton Quantity: 5000cartons/hour</p>', '2026-09-06 20:58:45');